// Pastas do Cérebro das Sócias que viram tarefas da equipe. Só arquivos criados nas últimas 3 horas.
const desde = $now.minus({ hours: 3 }).toUTC().toISO();
const pastas = [
  { id: '1XFhPf0jIdxKqEJJ4n3kUXJkQLl28lwtd', nome: 'Reuniões internas', cliente: null },
  { id: '1GzOers1azRTWDzcmTeQFpjN4up-gMGGq', nome: 'Projeto Virgínia', cliente: 'Virgínia' },
];
return pastas.map(p => ({ json: { ...p, q: `'${p.id}' in parents and mimeType = 'application/vnd.google-apps.document' and trashed = false and createdTime > '${desde}'` } }));

// Um item por arquivo novo, levando a pasta junto
const out = [];
$input.all().forEach((it, i) => {
  const p = $('Pastas').all()[i]?.json || {};
  for (const f of (it.json.files || [])) out.push({ json: { id: f.id, name: f.name, createdTime: f.createdTime, cliente: p.cliente, pasta: p.nome } });
});
return out;

// Lê as notas do Gemini (seção "Próximas etapas") e monta a reunião para a fila de aprovação.
const meta = $('Separar arquivos').item.json;
const bruto = String($json.data ?? $json.body ?? $json ?? '');
const texto = bruto.replace(/\r/g, '').replace(/\\([\[\]()_*#.-])/g, '$1');

// Título "2026-11-26 · [EuforIA] Projeto Virgínia" -> data e nome
const m = String(meta.name || '').match(/^(\d{4}-\d{2}-\d{2})\s*[·\-]\s*(.+)$/);
const data = m ? m[1] : String(meta.createdTime || '').slice(0, 10);
const nomeReuniao = (m ? m[2] : meta.name || 'Reunião').trim();

// Recorta a seção
const linhas = texto.split('\n');
const ini = linhas.findIndex(l => /pr[óo]ximas\s+etapas/i.test(l));
if (ini < 0) return [];   // sem a seção: a reunião não gera nada
let fim = linhas.length;
for (let i = ini + 1; i < linhas.length; i++) {
  if (/^\s*#{1,4}\s*\**\s*(detalhes|transcri)/i.test(linhas[i]) || /^\s*\**\s*detalhes\s*\**\s*$/i.test(linhas[i])) { fim = i; break; }
}
const secao = linhas.slice(ini + 1, fim);

// Quem do time é quem (nome da nota -> como o gestão conhece)
const ALIAS = { 'raphael jatobá passos': 'Raphael', 'raphael': 'Raphael', 'rapha': 'Raphael', 'rafael rodrigues': 'Rafael', 'bia cs - euforia digital': 'Bia', 'bia': 'Bia', 'jony nascimento': 'Jony' };
const SEM_DONO = ['euforia digital', 'euforia', 'time', 'equipe'];

// Prazo padrão: 2 dias úteis depois da reunião (a Bia ajusta na tela)
const somarUteis = (iso, n) => { const d = new Date(iso + 'T12:00:00Z'); let f = 0; while (f < n) { d.setUTCDate(d.getUTCDate() + 1); const w = d.getUTCDay(); if (w !== 0 && w !== 6) f++; } return d.toISOString().slice(0, 10); };
const prazo = /^\d{4}-\d{2}-\d{2}$/.test(data) ? somarUteis(data, 2) : null;

const itens = [];
let atual = null;
for (const l of secao) {
  const t = l.trim();
  if (!t) continue;
  const r = t.match(/^(?:[-*•●○▪]\s*)?\[(.+?)\]\s*([^:]{2,120}?):\s*(.*)$/);
  if (r) {
    const quem = r[1].trim();
    const chave = quem.toLowerCase();
    atual = { titulo: r[2].trim(), responsavel: SEM_DONO.includes(chave) ? null : (ALIAS[chave] || quem), prazo, destino: 'equipe', notas: r[3].trim() || null };
    itens.push(atual);
  } else if (atual && !/^#{1,4}\s/.test(t)) {
    atual.notas = ((atual.notas || '') + ' ' + t).trim();   // continuação da descrição
  }
}
if (!itens.length) return [];

return [{ json: {
  titulo: nomeReuniao, data, tipo: 'interna', origem: meta.id, cliente: meta.cliente || null,
  resumo: (texto.match(/###\s*\**Resumo\**\s*\n([\s\S]*?)\n###/i) || [, ''])[1].replace(/\*\*/g, '').replace(/\s+/g, ' ').trim().slice(0, 600) || null,
  itens: JSON.stringify(itens),
} }];
